svg.script:

var refreshSeatOverlays = function () {};

function normalizeSelectionLabel(label) {
    if (!label) {
        return label;
    }
    return label.replace(/nie+niewybrane/g, 'niewybrane');
}

function applySelectionLabel(label, isSelected) {
    var normalized = normalizeSelectionLabel(label);
    if (isSelected) {
        return /\bniewybrane\b/.test(normalized)
            ? normalized.replace(/\bniewybrane\b/, 'wybrane')
            : normalized;
    }
    return /\bwybrane\b/.test(normalized)
        ? normalized.replace(/\bwybrane\b/, 'niewybrane')
        : normalized;
}

var SVGPlaces = (function () {

    var svgLastPlace     = 'undefined';
    var svgLastType      = 'undefined';
    var svgLastDirection = 'undefined';
    var imgServerUrl     = 'https://img.intercity.pl/grm/';

    /* dostępne miejsce */
    var p1Img = {
        'R': imgServerUrl + '1R.png',
        'L': imgServerUrl + '1L.png',
        'U': imgServerUrl + '1U.png',
        'B': imgServerUrl + '1B.png'
    };

    /* wybrane miejsce */
    var chosenImg = {
        'R': imgServerUrl + '2R.png',
        'L': imgServerUrl + '2L.png',
        'U': imgServerUrl + '2U.png',
        'B': imgServerUrl + '2B.png'
    };

    /* niedostępne miejsce */
    var unavailableImg = {
        'R': imgServerUrl + '3R.png',
        'L': imgServerUrl + '3L.png',
        'U': imgServerUrl + '3U.png',
        'B': imgServerUrl + '3B.png'
    };

    /* miejsce dla parlamentarzysty */
    var poselImg = {
        'R': imgServerUrl + '4R.png',
        'L': imgServerUrl + '4L.png',
        'U': imgServerUrl + '4U.png',
        'B': imgServerUrl + '4B.png'
    };

    /* zmienne dla obsługi za pomocą klawiatury */
    var availableForSelection = [].slice.call(document.getElementsByClassName('place')).filter(function (place) {
        return (place.getAttributeNS(null, 'status') === '1' || place.getAttributeNS(null, 'status') === '4');
    });

    var currentSelection = 0;
    var previousSelection = 0;

    if (availableForSelection.length > 0) {
        currentSelection = availableForSelection.length - 1;
    } else {
        currentSelection = 0;
        previousSelection = 0;
    }

    /* callbacks */
    var selectPlaceCallback;
    var initPlaceCallback;

    var toggleOff = function (targetElement, duration) {
        if (typeof targetElement.animate === 'function') {
            targetElement.animate( [{opacity: 1}, {opacity: 0}], {duration: duration, fill: 'forwards'} );
        } else {
            targetElement.setAttribute('opacity', 0);
        }
    };

    var toggleOn = function (targetElement, duration) {
        if (typeof targetElement.animate === 'function') {
            targetElement.animate( [{opacity: 0}, {opacity: 1}], {duration: duration, fill: 'forwards'} );
        } else {
            targetElement.setAttribute('opacity', 1);
        }
    };

    var getPlaceImage = function (type, direction, status, isParliament) {
        switch (status) {
            case '1':
                return isParliament ? poselImg[direction] : p1Img[direction];
            case '2':
            case '3':
                return unavailableImg[direction];
            case '4':
                return chosenImg[direction];
            default:
                return p1Img[direction];
        }
    };

    var setCurrent = function (placeIndex) {
        if (placeIndex > -1 && placeIndex < availableForSelection.length) {
            previousSelection = currentSelection;
            currentSelection = placeIndex;
            availableForSelection[previousSelection].setAttribute('opacity', '1');
            availableForSelection[currentSelection].setAttribute('opacity', '0.5');
        }
    };

    var svgTakePlace = function (tokens) {
        if( typeof tokens !== 'undefined' && tokens[ 2 ] === '1' ) {
            var svgPlace = document.getElementById( tokens[ 0 ] + '-img-' + tokens[ 2 ] + '-' + tokens[ 3 ] );
            var svgPlaceNumber = document.getElementById( tokens[ 0 ] + '-txt-' + tokens[ 2 ] + '-' + tokens[ 3 ] ).textContent;
            var svgSpecial = document.getElementById( tokens[ 0 ] + '-special-' + tokens[ 2 ] + '-' + tokens[ 3 ] );
            var status = svgPlace.getAttributeNS(null, 'status');
            if ( status === '1' || status === '4' ) {
                if (typeof selectPlaceCallback !== 'undefined') {
                    selectPlaceCallback.call(this, tokens, svgPlace, svgPlaceNumber, svgSpecial);
                }
            }
        }
    };

    var svgInitPlace = function (tokens) {
        if( typeof tokens !== 'undefined' && tokens[ 2 ] === '1' ) {
            var svgPlace = document.getElementById( tokens[ 0 ] + '-img-' + tokens[ 2 ] + '-' + tokens[ 3 ] );
            var svgPlaceNumber = document.getElementById( tokens[ 0 ] + '-txt-' + tokens[ 2 ] + '-' + tokens[ 3 ] ).textContent;
            var svgSpecial = document.getElementById( tokens[ 0 ] + '-special-' + tokens[ 2 ] + '-' + tokens[ 3 ] );
            var status = svgPlace.getAttributeNS(null, 'status');
            if ( status === '1' || status === '4' ) {
                if (typeof initPlaceCallback !== 'undefined') {
                    initPlaceCallback.call(this, tokens, svgPlace, svgPlaceNumber, svgSpecial);
                }
            }
        }
    };

    var findTokensForPlaceNumber = function (placeNumber) {
        var resultTokens;
        var foundPlaceNumber;
        for (var i = 0; i < availableForSelection.length; i++) {
            if (typeof availableForSelection[i] !== 'undefined') {
                var tokens = availableForSelection[i].id.split('-');
                foundPlaceNumber = document.getElementById( tokens[ 0 ] + '-txt-' + tokens[ 2 ] + '-' + tokens[ 3 ] ).textContent;
                if (parseInt(foundPlaceNumber) === parseInt(placeNumber)) {
                    resultTokens = tokens;
                    break;
                }
            }
        }
        return resultTokens;
    };

    return {
        getChosenImg : function(direction) {
            return chosenImg[direction];
        },

        setOnSelectPlace : function(callback) {
            selectPlaceCallback = callback;
        },

        setOnInitPlace : function(callback) {
            initPlaceCallback = callback;
        },

        switchSelectedPlace : function (tokens, svgPlace, preserveLast) {
        if (svgPlace) {
            var title = document.getElementById(tokens[0] + '-title-' + tokens[2] + '-' + tokens[3]);
            var isParliament = svgPlace.getAttributeNS(null, 'parliament') === 'true';
            switch (svgPlace.getAttributeNS(null, 'status')) {

                    case '1':
                        if (preserveLast && svgLastPlace !== 'undefined') {
                            svgPlace.parentNode.setAttribute('aria-label', applySelectionLabel(svgPlace.parentNode.getAttribute('aria-label'), false))
                            if (title) {
                               title.textContent = applySelectionLabel(title.textContent, false);
                            }
                            svgPlace.parentNode.setAttribute('aria-selected', false)
                            svgLastPlace.setAttribute('status', '1');
                            svgLastPlace.setAttribute('xlink:href', getPlaceImage(svgLastType, svgLastDirection, '1', isParliament));
                        }
                        svgPlace.parentNode.setAttribute('aria-label', applySelectionLabel(svgPlace.parentNode.getAttribute('aria-label'), true))
                            if (title) {
                               title.textContent = applySelectionLabel(title.textContent, true);
                            }
                        svgPlace.parentNode.setAttribute('aria-selected', true)
                        svgPlace.setAttribute('status', '4');
                        svgPlace.setAttribute('xlink:href', getPlaceImage(tokens[ 2 ], tokens[ 3 ], '4', isParliament));
                        refreshSeatOverlays();
                        break;
                    case '4':
                        svgPlace.parentNode.setAttribute('aria-label', applySelectionLabel(svgPlace.parentNode.getAttribute('aria-label'), false))
                            if (title) {
                               title.textContent = applySelectionLabel(title.textContent, false);
                            }
                        svgPlace.parentNode.setAttribute('aria-selected', false)
                        svgPlace.setAttribute('status', '1');
                        svgPlace.setAttribute('xlink:href', getPlaceImage(tokens[ 2 ], tokens[ 3 ], '1', isParliament));
                        refreshSeatOverlays();
                        break;
                }

                if (preserveLast) {
                    svgLastPlace = svgPlace;
                    svgLastType = tokens[ 2 ];
                    svgLastDirection = tokens[ 3 ];
                }
            }
        },

        /* mouse */

        takePlace : function( event ) {
            event = event || window.event;
            var element;
            if (typeof event.srcElement !== 'undefined') {
                element = event.srcElement;
            } else {
                element = event.target;
            }

            var tokens = element.getAttributeNS(null, 'id').split( '-' );
            svgTakePlace(tokens);
        },

        hideSpecialLayer : function( event ) {
            event = event || window.event;
            var element;
            if (typeof event.srcElement !== 'undefined') {
                element = event.srcElement;
            } else {
                element = event.target;
            }
            targetElement = element.parentNode;
            specialSeatImage = targetElement.querySelectorAll('.special');
            specialText = targetElement.querySelectorAll('.seatNum');
            toggleOff(specialSeatImage.item(0), 150);
            toggleOn(specialText.item(0), 150);
        },

        showSpecialLayer : function ( event ) {
            event = event || window.event;
            var element;
            if (typeof event.srcElement !== 'undefined') {
                element = event.srcElement;
            } else {
                element = event.target;
            }
            targetElement = element.parentNode;
            specialSeatImage = targetElement.querySelectorAll('.special');
            specialText = targetElement.querySelectorAll('.seatNum');
            toggleOff(specialText.item(0), 150);
            toggleOn(specialSeatImage.item(0), 150);
        },

        /* keyboard */

        slidePlace: function (forward) {
            placesCounter = availableForSelection.length;
            if (forward) {
                calculated_index = (currentSelection + 1) % placesCounter;
            } else {
                calculated_index = (((currentSelection - 1) % placesCounter) + placesCounter) % placesCounter;
        }
            setCurrent(calculated_index);
        },

        takeCurrentPlace: function () {
            var tokens = availableForSelection[currentSelection].id.split('-');
            svgTakePlace(tokens);
        },

        takePlaceForNumber: function (placeNumber) {
            var tokens = findTokensForPlaceNumber(placeNumber);
            svgTakePlace(tokens);
        },

        /* initial place */

        initPlace: function (placeNumber) {
            var tokens = findTokensForPlaceNumber(placeNumber);
            svgInitPlace(tokens);
        },

        /* mark place as unavailable */

        markPlaceAsUnavailable: function (placeNumber) {
            var tokens = findTokensForPlaceNumber(placeNumber);
            if (tokens) {
                var svgPlace = document.getElementById( tokens[ 0 ] + '-img-' + tokens[ 2 ] + '-' + tokens[ 3 ] );
                var isParliament = svgPlace.getAttributeNS(null, 'parliament') === 'true';
                var svgGroup = svgPlace.parentNode;
                if (svgPlace && svgGroup) {
                    svgPlace.setAttribute('status', '3');
                    svgPlace.setAttribute('xlink:href', getPlaceImage(tokens[ 2 ], tokens[ 3 ], '3', isParliament));
                    refreshSeatOverlays();
                }
            }
        },

        /* mark place as available */

        markPlaceAsAvailable: function (placeNumber) {
            var tokens = findTokensForPlaceNumber(placeNumber);
            if (tokens) {
                var svgPlace = document.getElementById( tokens[ 0 ] + '-img-' + tokens[ 2 ] + '-' + tokens[ 3 ] );
                var isParliament = svgPlace.getAttributeNS(null, 'parliament') === 'true';
                var svgGroup = svgPlace.parentNode;
                if (svgPlace && svgGroup) {
                    svgPlace.setAttribute('status', '1');
                    svgPlace.setAttribute('xlink:href', getPlaceImage(tokens[ 2 ], tokens[ 3 ], '1', isParliament));
                    refreshSeatOverlays();
                }
            }
        }

    };
})();

/* default callbacks */
SVGPlaces.setOnSelectPlace(function (tokens, svgPlace, svgPlaceNumber, svgSpecial) { SVGPlaces.switchSelectedPlace(tokens, svgPlace, false) });
SVGPlaces.setOnInitPlace(function (tokens, svgPlace, svgPlaceNumber, svgSpecial) { SVGPlaces.switchSelectedPlace(tokens, svgPlace, false) });

/* events assignment on SVG rects (invoked by HTML overlay buttons) */
var elementsPlace = document.getElementsByClassName('place-rect');
for (var i = 0; i < elementsPlace.length; i++) {
    elementsPlace[i].addEventListener('click', SVGPlaces.takePlace, false);
    specialElements = elementsPlace[i].parentNode.getElementsByTagName('eic:special');
    if (specialElements.length > 0 && (parseInt(specialElements[0].getAttributeNS(null, 'ref')) <= 8)
      && specialElements[0].parentNode.querySelectorAll('.special').length > 0) {
        elementsPlace[i].addEventListener('mouseover', SVGPlaces.hideSpecialLayer, false);
        elementsPlace[i].addEventListener('mouseout', SVGPlaces.showSpecialLayer, false);
    }
}
